#!/usr/bin/env python3
"""Generaciones del voto  03 / grafos de similitud

a partir de HTML generado por  experimentos 01/02

Grafo kNN simétrico por unión (15,30,60 vecinos); afinidad local
exp(-d_ij²/(sigma_i*sigma_j)), sigma=distancia al séptimo vecino.
k=2..8.
Semillas 0..9; n_init=30; max_iter=500; seed0 mostrado. 


"""
import argparse,hashlib,itertools,json,re,platform
from pathlib import Path
import numpy as np
import scipy
from scipy.sparse import csr_matrix
from scipy.sparse.csgraph import laplacian,connected_components
from scipy.sparse.linalg import eigsh
import sklearn
from sklearn.neighbors import NearestNeighbors
from sklearn.cluster import KMeans
from sklearn.metrics import adjusted_rand_score,silhouette_samples
from threadpoolctl import threadpool_limits

YEARS=[2009,2012,2015,2018,2021,2024]
NEIGHBORS=[15,30,60]
TEMPLATE = '<!doctype html>\n<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">\n<title>Generaciones del voto · Explorador 03</title>\n<style>\n:root{--ink:#142c3a;--muted:#617481;--paper:#f4f5f1;--line:#dce3df;--teal:#087f83;--gold:#d39b41;--navy:#102c3a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}header{background:var(--navy);color:#fff;padding:30px 5% 28px;position:relative}header:after{content:\'2009 → 2024\';position:absolute;right:5%;bottom:32px;color:#9ccecc;font:600 24px monospace}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:#9ccecc}h1{font-size:clamp(28px,4vw,42px);letter-spacing:-1.4px;margin:8px 0}header p{margin:0;color:#c5d5db;max-width:65%}main{max-width:1500px;margin:auto;padding:24px 4% 50px}h2{font-size:21px;letter-spacing:-.4px;margin:0 0 6px}h3{font-size:16px;margin:0 0 12px}.sub{color:var(--muted);font-size:13px;margin:0 0 16px}.notice{border-left:4px solid var(--gold);padding:13px 18px;background:#fff5df;font-size:13px;margin:0 0 22px}.controls{display:grid;grid-template-columns:1.25fr .8fr 1.2fr 1.1fr 1.4fr;gap:14px;background:white;padding:18px;border:1px solid var(--line);border-radius:12px}label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--muted)}select,input{width:100%;background:#fff;border:1px solid #c7d3d1;border-radius:6px;padding:10px 8px;color:var(--ink);margin-top:5px;font:14px system-ui}input:focus,select:focus,button:focus-visible{outline:3px solid #a6d6d3;outline-offset:2px}button{border:1px solid #bccfca;background:white;color:var(--ink);padding:8px 12px;border-radius:6px;cursor:pointer;font:600 12px system-ui}button:hover{background:#e9f3f0}button.active{background:var(--teal);color:white;border-color:var(--teal)}button:disabled{opacity:.45;cursor:not-allowed}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.stat{background:white;padding:18px;border:1px solid var(--line);border-radius:10px}.stat b{display:block;font-size:29px;letter-spacing:-1px}.stat span{font-size:12px;color:var(--muted)}nav{display:flex;gap:8px;margin:22px 0;flex-wrap:wrap}nav button{padding:11px 17px}section[hidden]{display:none}.card{min-width:0;overflow-x:auto;background:white;border:1px solid var(--line);border-radius:12px;padding:24px;margin-bottom:18px}.grid{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}.row{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:space-between}.chip{display:inline-flex;gap:8px;align-items:center;background:#eaf4f1;border:1px solid #c9ded7;border-radius:30px;padding:5px 10px;margin:3px;font-size:12px}.chip button{border:0;background:transparent;padding:0 3px}.pill{display:inline-block;padding:3px 7px;border-radius:5px;background:#fff2d6;color:#77551d;font-size:11px}.good{background:#e1f3ea;color:#216247}.chart{width:100%;height:auto;min-height:240px}.axis{font:12px system-ui;fill:#667a83}.gridline{stroke:#e4ebe7;stroke-width:1}.data-dot{cursor:pointer}.data-dot:hover{stroke:#142c3a;stroke-width:3}.muted{color:var(--muted)}.small{font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;color:var(--muted);background:#f6f8f5;position:sticky;top:0;font-size:11px}td,th{padding:10px;border-bottom:1px solid #e5ebe7}tbody tr:hover{background:#f0f7f4}.tablewrap{overflow:auto;max-height:440px;margin-top:12px}#tooltip{display:none;position:fixed;z-index:100;background:#102c3a;color:white;padding:13px 16px;border-radius:9px;font-size:12px;box-shadow:0 8px 30px #102c3a40;pointer-events:none;max-width:310px}#tooltip strong{font-size:14px;display:block;margin-bottom:4px}a{color:var(--teal)}details{border-top:1px solid var(--line);padding:14px 0}summary{cursor:pointer;font-weight:600}code,pre{font:12px/1.6 monospace;background:#f1f5f2;white-space:pre-wrap;overflow-wrap:anywhere}pre{padding:16px}footer{font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:20px}.empty{padding:40px 20px;border:1px dashed #b9cbc5;border-radius:8px;background:#f7faf7;text-align:center;color:var(--muted)}.keyline{width:25px;display:inline-block;border-top:2px solid;margin-right:6px;vertical-align:middle}#legend{font-size:12px;margin:12px 0}.filehash{max-width:240px;overflow-wrap:anywhere;font:10px monospace}.hscroll{overflow:auto}#modelMetrics .stats{grid-template-columns:repeat(3,1fr)}.two{display:grid;grid-template-columns:1fr 1fr;gap:16px}ul{padding-left:20px}.statusline{color:#835d20;font-size:12px;margin-top:8px}@media(max-width:950px){header:after{display:none}header p{max-width:100%}.controls{grid-template-columns:1fr 1fr}.grid,.two{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.card{padding:16px}}@media(max-width:500px){#modelMetrics .stats{grid-template-columns:1fr 1fr}.chart{min-width:640px}main{padding:18px 12px}.controls{grid-template-columns:1fr}.stat b{font-size:24px}h1{font-size:30px}}\n.profilegrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:18px 0}.profile{border:1px solid var(--line);border-top:4px solid;border-radius:9px;padding:16px;min-width:0}.profile h3{font-size:15px}.profile svg{width:100%;height:auto}.profile button{margin:4px 2px;font-size:11px}.profile p{font-size:12px}@media(max-width:950px){.profilegrid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.profilegrid{grid-template-columns:1fr}}</style></head><body>\n<header><div class="eyebrow">Investigación electoral · Experimentos 01 + 02 + 03</div><h1>Generaciones del voto</h1><p>Explora cohortes juveniles de 2009 a lo largo de seis elecciones. Observaciones agregadas, territorios y trayectorias.</p></header>\n<main>\n<div id="status" class="notice"></div>\n<div class="controls">\n <label>Cohorte inicial · 2009<select id="cohort"><option value="0">18–20 años → 33–35 en 2024</option><option value="1">21–23 años → 36–38 en 2024</option><option value="2">24–26 años → 39–41 en 2024</option><option value="3">27–29 años → 42–44 en 2024</option></select></label>\n <label>Sexo registrado<select id="sex"><option value="0">Hombres (0)</option><option value="1">Mujeres (1)</option></select></label>\n <label>Entidad<select id="state"></select></label>\n <label>Indicador<select id="metric"><option value="centered">Trayectoria centrada · pp</option><option value="p">SV / LN · %</option><option value="specified">SV / (SV + NV) · %</option><option value="q">NS / LN · %</option><option value="relative">Diferencia ref. nacional · pp</option></select></label>\n <label>Buscar municipio<input id="search" placeholder="Nombre o clave INE…" type="search"></label>\n</div>\n<div class="stats"><div class="stat"><b id="nMunicipal">—</b><span>Municipios en la selección</span></div><div class="stat"><b id="nComplete">—</b><span>Con seis agregados válidos</span></div><div class="stat"><b id="nGeo">—</b><span>Con el mismo conjunto de secciones</span></div><div class="stat"><b id="nMissing">—</b><span>Observaciones ausentes o no válidas</span></div></div>\n<nav aria-label="Vistas"><button class="active" data-tab="trajectories">01 / Trayectorias</button><button data-tab="comparison">02 / Comparador</button><button data-tab="clusters">03 / Agrupamientos</button><button data-tab="quality">04 / Calidad y método</button></nav>\n<section id="trajectories"><div class="card"><div class="row"><div><h2>Una cohorte, seis momentos</h2><p class="sub">Pasa el cursor por un punto para consultar sus conteos. Haz clic para añadir el municipio al comparador.</p></div><button id="download">Descargar selección CSV</button></div><div id="lineCaption" class="small muted"></div><svg id="lines" class="chart" viewBox="0 0 1000 390" role="img" aria-label="Trayectorias por municipio"></svg><div class="small muted">Líneas discontinuas: continuidad territorial pendiente. No prueban persistencia de una población o territorio constante. Los huecos no se interpolan.</div></div>\n<div class="grid"><div class="card"><h2>Inicio y final observados</h2><p class="sub">Cada punto es un municipio: 2009 en el eje horizontal y 2024 en el vertical. No es una proyección de clústeres.</p><svg id="scatter" class="chart" viewBox="0 0 600 380" role="img" aria-label="Comparación entre 2009 y 2024"></svg><p id="scatterCaption" class="small muted"></p></div><div class="card"><h2>Encuentra un municipio</h2><p class="sub">Usa la búsqueda superior o añade municipios desde la tabla. El comparador conserva las selecciones al cambiar de entidad.</p><div id="municipalTable" class="tablewrap"></div><div class="row small" style="margin-top:10px"><button id="prev">← Anterior</button><span id="pageLabel"></span><button id="next">Siguiente →</button></div></div></div></section>\n<section id="comparison" hidden><div class="card"><h2>Comparador de territorios</h2><p class="sub">Hasta ocho municipios. La cohorte, el sexo y el indicador siguen los filtros superiores; entidad y búsqueda no ocultan los municipios fijados.</p><div id="pins"></div><svg id="compareChart" class="chart" viewBox="0 0 1000 390" role="img" aria-label="Trayectorias de municipios seleccionados"></svg><div id="legend"></div><div id="compareTable" class="tablewrap"></div><button id="clearPins">Vaciar comparador</button></div></section>\n<section id="clusters" hidden><div class="card"><div class="row"><h2>Agrupamientos y estabilidad</h2><button id="downloadClusters">Descargar clasificación CSV</button></div><p class="sub">Los modelos exploratorios se ajustan por cohorte y sexo, con seis observaciones válidas. La continuidad cartográfica no se da por verificada. Los filtros de entidad no vuelven a ajustar el modelo. Los experimentos 02 y 03 abren seis perfiles candidatos para examinarlos; puedes contrastar de dos a ocho grupos. No son seis tipos universales ni una solución validada. El experimento 01 abre la mayor silueta del estrato. Los números de grupo no equivalen entre modelos.</p><div id="modelStatus"></div><div class="two" style="margin:18px 0"><label>Experimento<select id="experiment"><option value="graph">03 · Grafo de similitud</option><option value="centered">02 · Forma de la trayectoria</option><option value="level">01 · Nivel de participación</option></select></label><label>Solución<select id="model"></select></label><label>Grupo<select id="clusterGroup"></select></label></div><div id="modelMetrics"></div><div id="graphPanel" hidden><h3>Mapa de similitud de las trayectorias</h3><p class="small muted">Proyección de los dos autovectores no triviales del grafo. No es un mapa geográfico y las distancias dibujadas no son las distancias completas del modelo. Cada punto representa un municipio de la cohorte y sexo elegidos. Pasa el cursor o pulsa para comparar.</p><div id="graphFacts" class="small"></div><svg id="graphPlot" class="chart" viewBox="0 0 1000 450" aria-label="Proyección de similitud"></svg><div id="graphRobustness"></div></div><h3>Perfiles candidatos de esta cohorte y sexo</h3><p class="small muted">Curvas medias del modelo completo, sin filtrar por entidad. Los nombres describen extremos y máximos observados, no comportamiento individual. Ejemplos: municipios cercanos al centroide, hasta tres entidades distintas. Pulsa un ejemplo para incorporarlo al comparador.</p><div id="profiles" class="profilegrid"></div><div id="transition" class="hscroll"></div><h3>Perfiles medios de los grupos</h3><p class="small muted">Media simple de porcentajes municipales, según el indicador seleccionado. Pasa el cursor por cada celda. Estas etiquetas son candidatas y deben contrastarse entre métodos.</p><div id="groupSummary" class="hscroll"></div><h3 style="margin-top:24px">Prueba de estabilidad: omitir una elección</h3><p class="small muted">El modelo principal usa las seis elecciones. Sólo en esta prueba se ajusta otro modelo con cinco: sirve para detectar dependencia de un año. Una caída electoral real puede ser sustantiva aunque reduzca esta estabilidad; no se descarta automáticamente.</p><svg id="stabilityPlot" class="chart" viewBox="0 0 1000 230" aria-label="ARI al retirar cada elección"></svg><svg id="clusterChart" class="chart" viewBox="0 0 1000 390" role="img" aria-label="Trayectorias por agrupamiento"></svg><div id="clusterTable" class="tablewrap"></div></div></section>\n<section id="quality" hidden><div class="card"><h2>Qué sabemos y qué falta verificar</h2><div class="two"><div><h3>Lectura correcta de los datos</h3><ul class="small"><li>Son cohortes aproximadas por edad cumplida en cada jornada; las fechas cambian y sus límites de nacimiento no coinciden exactamente.</li><li>No se sigue a los mismos individuos. Migración y cambios del registro pueden modificar la composición.</li><li>SV: marca de voto; NV: sin marca; NS: participación no especificada; LN: lista nominal contabilizada.</li><li>No se contempla la participación en casillas especiales ni desde el extranjero, según los diccionarios.</li><li>El código 2 de 2024 no se reconstruye en años anteriores. 2025 es una extensión independiente, fuera de este experimento.</li></ul></div><div><h3>Controles que condicionan el modelo</h3><ul class="small"><li>No hay imputación, interpolación ni sustitución por ceros.</li><li>Una clave repetida por sección, edad y sexo invalida los agregados afectados; no se deduplica automáticamente.</li><li>Se exige LN positivo, identidad LN = SV + NV + NS y las tres edades representadas en el agregado municipal.</li><li>No se ha demostrado cobertura completa de secciones contra un catálogo externo.</li><li>El catálogo geográfico adjunto contiene nombres, no polígonos: no se fabrica un mapa municipal.</li><li>Modo exploratorio autorizado: la continuidad territorial pendiente no impide ajustar modelos. Se contrasta la solución al restringirla a municipios con el mismo conjunto de secciones en las seis elecciones. Esa estabilidad observada no demuestra límites cartográficos invariables.</li></ul></div></div>\n<details open><summary>Resumen de auditoría · todos los registros de los seis ZIP ordinarios</summary><div id="auditSummary" class="hscroll"></div><p class="small muted">Las incidencias pueden solaparse. Los conteos abarcan todas las edades y categorías de los archivos, no sólo las cuatro cohortes del explorador.</p></details>\n<details><summary>Observaciones de esta selección y motivo de exclusión</summary><div id="exclusionTable" class="tablewrap"></div></details>\n<details><summary>Modelos, parámetros y comparación de soluciones</summary><p class="small">K-means: k=2…8, k-means++, n_init=50, max_iter=500, tol=0.0001, semillas 0…19; ajuste mostrado: semilla 0. Ward: enlace de mínima variación con distancia euclidiana. Cada municipio y elección tienen el mismo peso. Experimento 01: seis tasas en escala porcentual. Experimento 02: se resta a cada municipio su propia media de las seis elecciones; se conservan las amplitudes en puntos porcentuales, sin dividir por desviación estándar. Al retirar una elección se vuelve a centrar con las cinco restantes. Las siluetas de espacios distintos no se comparan como si midieran la misma estructura. Se exploran k=2…8; k=6 se abre para examinar candidatos, no por superioridad estadística. La estabilidad de cada grupo usa el máximo Jaccard frente a los grupos del reajuste sin una elección: se reportan mínimo y media de seis reajustes. No es una probabilidad de pertenencia.</p><p class="small">Silueta: cohesión y separación. ARI: acuerdo de particiones; se comparan todos los pares de semillas y se excluye una elección cada vez. Sensibilidad: repetir con SV/(SV+NV) sobre las mismas unidades con denominador válido. Ninguna métrica acredita por sí sola validez sociológica. No se identifican efectos causales de edad, periodo o cohorte.</p><p class="small">Restar la misma referencia nacional a todos los municipios de un estrato no altera las distancias euclidianas; la vista relativa es interpretativa, no un modelo distinto. La referencia nacional usa razones de sumas de todos los conteos disponibles del estrato/año, incluidos los municipios con edades ausentes; no se imputan esas ausencias. No se presenta si se detectan errores de conteos. Es una referencia de registros disponibles, no una garantía de cobertura nacional completa.</p></details>\n<details open><summary>Experimento 03 · grafos, IA y siguientes pruebas</summary><p class="small">Aprendizaje no supervisado mediante grafos de similitud: 15, 30 y 60 vecinos, escala local del séptimo vecino, unión simétrica. Laplaciano normalizado, k=2…8, autovectores normalizados por fila y K-means en ese espacio. Diez semillas, n_init=30. Se informa la conectividad; un grafo desconectado no se conecta artificialmente ni se presenta como una solución válida. El mapa usa dos autovectores no triviales y no determina las etiquetas.</p><p class="small">La silueta se calcula en las seis tasas centradas para poder compararla con K-means centrado. El objetivo espectral es diferente: una silueta menor no basta por sí sola para descartarlo. Se reconstruye todo el grafo en cada sensibilidad. Cambiar la vecindad prueba si las comunidades dependen de un ajuste arbitrario. La coincidencia entre métodos y la estabilidad al retirar elecciones son evidencias distintas.</p><p class="small">Próximo: mezclas gaussianas para pertenencia probabilística y perfiles ambiguos; después, comparación temporal y consenso entre métodos. DEC (aprendizaje profundo) se evaluará como experimento adicional, sin presuponer que mejora seis observaciones por trayectoria. Los LLM pueden redactar fichas basadas en resultados; no se utilizan para inventar atributos psicológicos ni asignar etiquetas estadísticas.</p><p class="small"><a href="https://proceedings.neurips.cc/paper/2004/hash/40173ea48d9567f1f393b20c855bb40b-Abstract.html">Zelnik-Manor y Perona: escala local</a> · <a href="https://proceedings.mlr.press/v48/xieb16.html">DEC: Xie y colaboradores</a></p><pre>pip install numpy scipy scikit-learn threadpoolctl\npython experimento_03.py --base-html explorador_generaciones.html --output-dir resultados_grafos</pre><p class="small">Entrada: HTML de los experimentos anteriores, también acepta esta versión para recalcularla. Reutiliza agregados y auditoría; no vuelve a leer ni modifica los ZIP. La carpeta de salida debe ser distinta a la del HTML de entrada.</p></details><details><summary>Reproducir los experimentos 01/02 y elegir el modo</summary><pre>pip install numpy pandas scipy scikit-learn threadpoolctl\npython experimento_02.py --input-dir ./originales --output-dir ./resultados\n\n# Modo exploratorio (predeterminado):\npython experimento_02.py --input-dir ./originales --output-dir ./resultados --reuse --mode exploratory\n\n# Alternativa estricta, sólo con evidencia territorial revisada:\npython experimento_02.py --input-dir ./originales --output-dir ./resultados --reuse --mode strict --territories ./territorios_verificados.csv\n\n# Columnas del CSV (no se incluyen aprobaciones ficticias):\nEDOCVE,MPIOCVE,estado,fuente,justificacion\n\n# estado: verificado / excluido / pendiente\n# Una verificación requiere fuente y justificación de continuidad 2009–2024.</pre><p class="small">El script verifica SHA-256 antes y después, conserva los originales y comprueba las huellas de los derivados al reutilizarlos. No necesitas Python para abrir este HTML.</p></details>\n<details><summary>Fuentes y fundamento metodológico</summary><ul class="small"><li><a href="https://doi.org/10.1016/0304-4076(85)90134-4" target="_blank" rel="noopener">Deaton (1985)</a>: cohortes en cortes transversales sucesivos; no convierte estos datos en un panel individual.</li><li><a href="https://doi.org/10.1080/01621459.1963.10500845" target="_blank" rel="noopener">Ward (1963)</a>: agrupamiento por función objetivo.</li><li><a href="https://doi.org/10.1016/0377-0427(87)90125-7" target="_blank" rel="noopener">Rousseeuw (1987)</a>: silueta.</li><li><a href="https://doi.org/10.1007/BF01908075" target="_blank" rel="noopener">Hubert y Arabie (1985)</a>: acuerdo entre particiones.</li><li><a href="https://doi.org/10.1016/j.csda.2006.11.025" target="_blank" rel="noopener">Hennig (2007)</a>: estabilidad y sus límites.</li><li><a href="https://scikit-learn.org/stable/modules/clustering.html" target="_blank" rel="noopener">Documentación de scikit-learn</a>: implementación y supuestos de k-means.</li><li><a href="https://ine.mx/transparencia/datos-abiertos/visualizacion-datos/conteos-censales-participacion/" target="_blank" rel="noopener">INE: plataforma CCPC</a>: declara cartografía de mayo de 2023 para su visualización. No se extrapola esa homologación automáticamente a los ZIP adjuntos; sus diccionarios difieren.</li></ul><p class="small">Las bandas de tres edades, la ponderación y la parrilla de parámetros son decisiones del diseño acordado. No se atribuyen a la bibliografía como reglas universales.</p></details>\n<details><summary>Archivos originales y huellas de integridad</summary><div id="sourceTable" class="tablewrap"></div><pre id="runtime"></pre></details>\n</div></section>\n<footer>Generaciones del voto · Explorador local, sin servicios externos ni datos personales. Los colores identifican municipios o grupos provisionales; no son categorías institucionales definitivas. <span id="build"></span></footer>\n</main><div id="tooltip" role="status"></div>\n<script id="dataset" type="application/json">__DATA__</script>\n<script>\n\'use strict\';\nconst D=JSON.parse(document.getElementById(\'dataset\').textContent), $=id=>document.getElementById(id);\nconst palette=[\'#087f83\',\'#ce8545\',\'#7561a8\',\'#3976af\',\'#bd5577\',\'#6c8744\',\'#a36e35\',\'#486b73\'];\nlet page=0,pinned=[],modelIndex=-1;\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst nf=new Intl.NumberFormat(\'es-MX\'),fmt=x=>x==null||!Number.isFinite(x)?\'—\':x.toFixed(2);\nconst norm=x=>String(x).normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\').toLowerCase();\nconst cval=()=>+$(\'cohort\').value,sval=()=>+$(\'sex\').value;\nfunction selected(){let q=norm($(\'search\').value),st=$(\'state\').value;return D.records.filter(r=>r.cohort===cval()&&r.sex===sval()&&(!st||r.ed===+st)&&(!q||norm(r.name+\' \'+r.key).includes(q))).sort((a,b)=>a.name.localeCompare(b.name,\'es\'));}\nfunction values(r){let kind=$(\'metric\').value;if(kind===\'centered\'){if(!r.complete)return Array(6).fill(null);let v=r.counts.map(x=>100*x[1]/x[0]),a=v.reduce((a,b)=>a+b,0)/6;return v.map(x=>x-a);}return r.counts.map((x,j)=>{if(!x)return null;if(kind===\'q\')return 100*x[3]/x[0];if(kind===\'specified\')return x[1]+x[2]>0?100*x[1]/(x[1]+x[2]):null;let p=100*x[1]/x[0];if(kind===\'relative\'){let n=D.national[`${r.cohort}-${r.sex}-${D.years[j]}`];return n?p-100*n[1]/n[0]:null;}return p;});}\nfunction tooltip(e,r,j){let x=r.counts[j],v=values(r)[j],a=D.bands[r.cohort]+D.years[j]-2009;\n $(\'tooltip\').innerHTML=`<strong>${esc(r.name)}</strong>${esc(r.state)} · INE ${r.key}<br>${D.years[j]} · ${a}–${a+2} años · ${r.sex?\'Mujeres\':\'Hombres\'}<br><b>${esc($(\'metric\').selectedOptions[0].text)}: ${fmt(v)}</b>${x?`<br>LN ${nf.format(x[0])} · SV ${nf.format(x[1])}<br>NV ${nf.format(x[2])} · NS ${nf.format(x[3])}<br>Indeterminación: ${fmt(100*x[3]/x[0])}%`:\'\'}${r.clusterLabel!=null?\'<br>Grupo provisional: \'+(r.clusterLabel+1):\'\'}<br>Cartografía: ${esc(r.geo)}<br>Mismo conjunto de secciones: ${r.stable_sections?\'sí\':\'no\'}<br><span style="color:#a8d2cc">Clic: añadir al comparador</span>`;\n $(\'tooltip\').style.display=\'block\';$(\'tooltip\').style.left=Math.max(8,Math.min(e.clientX+14,innerWidth-320))+\'px\';$(\'tooltip\').style.top=Math.max(8,Math.min(e.clientY+14,innerHeight-240))+\'px\';}\nfunction hideTip(){$(\'tooltip\').style.display=\'none\';}\nfunction addPin(key){if(!pinned.includes(key)){if(pinned.length>=8){alert(\'El comparador admite hasta ocho municipios. Retira uno para añadir otro.\');return;}pinned.push(key);}renderCompare();}\nfunction domain(rows){if(![\'relative\',\'centered\'].includes($(\'metric\').value))return [0,100];let v=rows.flatMap(values).filter(x=>x!==null);let m=Math.max(10,...v.map(Math.abs));m=Math.ceil(m/10)*10;return [-m,m];}\nfunction lineChart(id,rows,{colors=null,limit=80}={}){let svg=$(id),shown=rows.slice(0,limit),w=1000,h=390,p={l:65,r:65,t:24,b:52},[lo,hi]=domain(shown),x=j=>p.l+j*(w-p.l-p.r)/5,y=v=>h-p.b-(v-lo)/(hi-lo)*(h-p.t-p.b),html=\'\';\n for(let i=0;i<=5;i++){let v=lo+(hi-lo)*i/5;html+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}" class="gridline"/><text x="${p.l-10}" y="${y(v)+4}" text-anchor="end" class="axis">${v.toFixed(0)}</text>`;}\n D.years.forEach((yr,j)=>{html+=`<text x="${x(j)}" y="${h-24}" text-anchor="middle" class="axis">${yr}</text><text x="${x(j)}" y="${h-7}" text-anchor="middle" class="axis">${D.bands[cval()]+yr-2009}–${D.bands[cval()]+yr-2009+2} años</text>`;});\n shown.forEach((r,i)=>{let vs=values(r),color=colors?colors(r,i):palette[i%palette.length],dash=r.geo===\'verificado\'?\'\':\'stroke-dasharray="5 4"\';for(let j=1;j<6;j++)if(vs[j]!=null&&vs[j-1]!=null)html+=`<line x1="${x(j-1)}" y1="${y(vs[j-1])}" x2="${x(j)}" y2="${y(vs[j])}" stroke="${color}" stroke-width="${shown.length>20?1:2}" opacity="${shown.length>20?.4:.85}" ${dash}/>`;\n vs.forEach((v,j)=>{if(v!=null)html+=`<circle class="data-dot" data-i="${i}" data-j="${j}" cx="${x(j)}" cy="${y(v)}" r="${shown.length>20?3:4.5}" fill="${color}"><title>${esc(r.name)} · ${D.years[j]} · ${fmt(v)}</title></circle>`;});});\n if(!shown.length)html+=\'<text x="500" y="185" text-anchor="middle" class="axis">No hay municipios para esta vista.</text>\';\n svg.innerHTML=html;svg.querySelectorAll(\'.data-dot\').forEach(el=>{let r=shown[+el.dataset.i],j=+el.dataset.j;el.onmousemove=e=>tooltip(e,r,j);el.onmouseleave=hideTip;el.onclick=()=>addPin(r.key);});}\nfunction scatter(rows){let svg=$(\'scatter\'),valid=rows.filter(r=>values(r)[0]!=null&&values(r)[5]!=null),[lo,hi]=domain(valid),x=v=>60+(v-lo)/(hi-lo)*510,y=v=>325-(v-lo)/(hi-lo)*290,s=\'\';for(let i=0;i<=5;i++){let v=lo+(hi-lo)*i/5;s+=`<line x1="60" x2="570" y1="${y(v)}" y2="${y(v)}" class="gridline"/><text x="50" y="${y(v)+4}" text-anchor="end" class="axis">${v.toFixed(0)}</text><text x="${x(v)}" y="345" text-anchor="middle" class="axis">${v.toFixed(0)}</text>`;}s+=`<line x1="60" y1="325" x2="570" y2="35" stroke="#adbbb6" stroke-dasharray="4 4"/><text x="320" y="375" text-anchor="middle" class="axis">2009 · ${[\'relative\',\'centered\'].includes($(\'metric\').value)?\'pp\':\'%\'}</text><text x="14" y="180" transform="rotate(-90 14 180)" text-anchor="middle" class="axis">2024 · ${[\'relative\',\'centered\'].includes($(\'metric\').value)?\'pp\':\'%\'}</text>`;\n valid.forEach((r,i)=>{let v=values(r);s+=`<circle class="data-dot" data-i="${i}" cx="${x(v[0])}" cy="${y(v[5])}" r="4" opacity=".65" fill="#087f83"><title>${esc(r.name)}: ${fmt(v[0])} → ${fmt(v[5])}</title></circle>`;});svg.innerHTML=s;svg.querySelectorAll(\'circle\').forEach(el=>{let r=valid[+el.dataset.i];el.onmousemove=e=>tooltip(e,r,5);el.onmouseleave=hideTip;el.onclick=()=>addPin(r.key);});$(\'scatterCaption\').textContent=`${nf.format(valid.length)} municipios con ambos extremos válidos. La diagonal indica igualdad de los dos valores; no valida continuidad territorial.`;}\nfunction table(rows,where,includeAll=false){let shown=includeAll?rows:rows.slice(page*30,page*30+30);$(where).innerHTML=`<table><thead><tr><th>Municipio / entidad</th><th>2009</th><th>2024</th><th>Observaciones</th><th></th></tr></thead><tbody>${shown.map(r=>{let v=values(r);return `<tr><td><b>${esc(r.name)}</b><br>${esc(r.state)} · ${r.key}</td><td>${fmt(v[0])}</td><td>${fmt(v[5])}</td><td>${r.clusterLabel!=null?\'G\'+(r.clusterLabel+1)+\' · \':\'\'}${r.counts.filter(Boolean).length}/6<br><span class="pill ${r.geo===\'verificado\'?\'good\':\'\'}">${esc(r.geo)}</span></td><td><button data-pin="${r.key}" aria-label="Añadir ${esc(r.name)}">+</button></td></tr>`;}).join(\'\')}</tbody></table>`;$(where).querySelectorAll(\'[data-pin]\').forEach(b=>b.onclick=()=>addPin(b.dataset.pin));}\nfunction renderCompare(){let rs=pinned.map(key=>D.records.find(r=>r.key===key&&r.cohort===cval()&&r.sex===sval())).filter(Boolean);$(\'pins\').innerHTML=pinned.map((k,i)=>`<span class="chip">${esc(D.records.find(r=>r.key===k)?.name||k)}<button data-remove="${k}" aria-label="Quitar municipio">×</button></span>`).join(\'\')||\'<p class="muted">Añade municipios haciendo clic en los puntos o en el botón + de la tabla.</p>\';$(\'pins\').querySelectorAll(\'[data-remove]\').forEach(b=>b.onclick=()=>{pinned=pinned.filter(k=>k!==b.dataset.remove);renderCompare();});lineChart(\'compareChart\',rs);$(\'legend\').innerHTML=rs.map((r,i)=>`<span style="margin-right:18px"><span class="keyline" style="color:${palette[i]}"></span>${esc(r.name)} · ${esc(r.state)}</span>`).join(\'\');$(\'compareTable\').innerHTML=`<table><thead><tr><th>Municipio</th>${D.years.map(y=>`<th>${y}</th>`).join(\'\')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.name)}</td>${values(r).map((v,j)=>`<td title="${esc(r.reasons[j])}">${fmt(v)}${r.counts[j]?`<br><small>LN ${nf.format(r.counts[j][0])}</small>`:\'\'}</td>`).join(\'\')}</tr>`).join(\'\')}</tbody></table>`;}\nfunction renderModels(reset=false){let ms=D.models.map((m,i)=>({...m,index:i})).filter(m=>m.cohort===cval()&&m.sex===sval()&&m.experiment===$(\'experiment\').value);if(reset||!$(\'model\').options.length||!ms.some(m=>m.index===+$(\'model\').value)){$(\'model\').innerHTML=ms.map(m=>`<option value="${m.index}">${m.method===\'spectral\'?\'Espectral · \'+m.neighbors+\' vecinos\':m.method===\'ward\'?\'Ward\':\'K-means\'} · ${m.k} grupos · ${m.ids.length} municipios · silueta ${fmt(m.silhouette)}</option>`).join(\'\');if(ms.length)$(\'model\').value=String(($(\'experiment\').value===\'graph\'?ms.find(m=>m.neighbors===30&&m.k===6)||ms[0]:$(\'experiment\').value===\'centered\'?ms.find(m=>m.method===\'kmeans\'&&m.k===6)||ms[0]:ms.reduce((a,b)=>a.silhouette>=b.silhouette?a:b)).index);}let m=D.models[+$(\'model\').value];if(!ms.length){$(\'model\').disabled=true;$(\'clusterGroup\').disabled=true;$(\'modelStatus\').innerHTML=\'<div class="empty"><h3>Sin modelos ejecutados en este estrato</h3>La auditoría territorial sigue pendiente o no hay suficientes trayectorias elegibles. No se han inventado etiquetas ni resultados.<br>El Python incluye los modelos y la validación; se habilitan con un registro territorial documentado.</div>\';$(\'modelMetrics\').innerHTML=\'\';$(\'clusterChart\').innerHTML=\'\';$(\'clusterTable\').innerHTML=\'\';$(\'groupSummary\').innerHTML=\'\';$(\'stabilityPlot\').innerHTML=\'\';return;}\n $(\'model\').disabled=false;$(\'clusterGroup\').disabled=false;$(\'modelStatus\').innerHTML=\'<span class="pill good">Resultados calculados · clasificación exploratoria; número de grupo sin significado ordinal</span>\';if(reset||modelIndex!==+$(\'model\').value){$(\'clusterGroup\').innerHTML=\'<option value="">Todos los grupos</option>\'+m.sizes.map((n,i)=>`<option value="${i}">Grupo ${i+1} · ${n} municipios</option>`).join(\'\');modelIndex=+$(\'model\').value;}\n let labels=new Map(m.ids.map((id,i)=>[id,m.labels[i]])),rs=selected().filter(r=>labels.has(r.id)&&($(\'clusterGroup\').value===\'\'||labels.get(r.id)===+$(\'clusterGroup\').value)).map(r=>({...r,clusterLabel:labels.get(r.id)}));$(\'modelMetrics\').innerHTML=`<div class="stats"><div class="stat"><b>${fmt(m.silhouette)}</b><span>Silueta</span></div><div class="stat"><b>${fmt(m.seed_ari_median)}</b><span>ARI mediano entre semillas</span></div><div class="stat"><b>${fmt(minValid(m.jackknife_ari))}</b><span>ARI mínimo al excluir elección</span></div><div class="stat"><b>${fmt(m.specified_ari)}</b><span>ARI con participación especificada</span></div><div class="stat"><b>${fmt(m.territorial_ari)}</b><span>ARI · restricción territorial</span></div><div class="stat"><b>${nf.format(m.territorial_n)}</b><span>Municipios en sensibilidad territorial</span></div></div><p class="small">Sensibilidad por elección excluida: ${D.years.map((y,i)=>y+\': \'+fmt(m.jackknife_ari[i])).join(\' · \')}. Se muestran hasta 80 trayectorias; ${rs.length} municipios coinciden con los filtros.</p>`;lineChart(\'clusterChart\',rs,{colors:r=>palette[labels.get(r.id)%8]});table(rs,\'clusterTable\',true);renderGroupSummary(m,labels);renderStability(m);renderProfiles(m);renderGraph(m,rs);}\n\nfunction renderGroupSummary(m,labels){\n let all=D.records.filter(r=>labels.has(r.id));\n $(\'groupSummary\').innerHTML=\'<table><thead><tr><th>Grupo</th><th>Municipios</th><th>Silueta</th>\'+D.years.map(y=>\'<th>\'+y+\'</th>\').join(\'\')+\'</tr></thead><tbody>\'+Array.from({length:m.k},(_,g)=>{let rs=all.filter(r=>labels.get(r.id)===g);return \'<tr><td><span class="keyline" style="color:\'+palette[g%8]+\'"></span>G\'+(g+1)+\'</td><td>\'+rs.length+\'</td><td>\'+fmt(m.silhouette_by_group?.[g])+\'</td>\'+D.years.map((yr,j)=>{let v=rs.map(values).map(x=>x[j]).filter(x=>x!=null),mean=v.length?v.reduce((a,b)=>a+b,0)/v.length:null;let title=\'Grupo \'+(g+1)+\' · \'+yr+\' · \'+v.length+\' municipios; mínimo \'+fmt(v.length?Math.min(...v):null)+\'; máximo \'+fmt(v.length?Math.max(...v):null);return \'<td title="\'+esc(title)+\'" style="background:rgba(8,127,131,\'+(mean==null?0:Math.min(.5,Math.abs(mean)/180))+\')">\'+fmt(mean)+\'</td>\';}).join(\'\')+\'</tr>\';}).join(\'\')+\'</tbody></table><p class="small muted">Resumen del modelo completo: no cambia con el filtro de entidad. Las trayectorias individuales de abajo sí responden a entidad, búsqueda y grupo.</p>\';\n}\nfunction renderStability(m){let y=v=>170-(v+1)*70,x=j=>100+j*155;let s=\'\';[-1,0,1].forEach(v=>s+=\'<line class="gridline" x1="60" x2="975" y1="\'+y(v)+\'" y2="\'+y(v)+\'"/><text class="axis" x="45" y="\'+(y(v)+4)+\'">\'+v+\'</text>\');m.jackknife_ari.forEach((v,j)=>{if(v==null){s+=\'<text class="axis" x="\'+x(j)+\'" y="100">No calculado</text>\';return;}s+=\'<rect x="\'+x(j)+\'" y="\'+Math.min(y(v),y(0))+\'" width="75" height="\'+Math.max(1,Math.abs(y(v)-y(0)))+\'" fill="#087f83"><title>Sin \'+D.years[j]+\': ARI \'+fmt(v)+\'</title></rect><text class="axis" text-anchor="middle" x="\'+(x(j)+37)+\'" y="\'+(y(v)-8)+\'">\'+fmt(v)+\'</text><text class="axis" text-anchor="middle" x="\'+(x(j)+37)+\'" y="200">Sin \'+D.years[j]+\'</text>\';});$(\'stabilityPlot\').innerHTML=s;}\n\n\nfunction renderProfiles(m){\n $(\'profiles\').innerHTML=(m.profiles||[]).map(p=>{let v=$(\'metric\').value===\'centered\'?p.centered_mean:p.mean,lo=$(\'metric\').value===\'centered\'?-40:0,hi=$(\'metric\').value===\'centered\'?40:100;lo=Math.min(lo,...v);hi=Math.max(hi,...v);let x=j=>25+j*48,y=z=>115-(z-lo)/(hi-lo)*95;return `<article class="profile" style="border-top-color:${palette[p.group]}"><div class="small muted">G${p.group+1} · ${nf.format(p.n)} municipios</div><h3>${esc(p.name)}</h3><svg viewBox="0 0 300 145" role="img" aria-label="Curva media del grupo ${p.group+1}"><line x1="25" x2="265" y1="${y(0)}" y2="${y(0)}" stroke="#ccc"/><polyline points="${v.map((z,j)=>x(j)+\',\'+y(z)).join(\' \')}" fill="none" stroke="${palette[p.group]}" stroke-width="3"/>${v.map((z,j)=>`<circle cx="${x(j)}" cy="${y(z)}" r="5" fill="${palette[p.group]}"><title>${D.years[j]}: ${fmt(z)} ${$(\'metric\').value===\'centered\'?\'pp centrados\':\'% SV/LN\'}; NS/LN ${fmt(p.q_mean[j])}%</title></circle><text x="${x(j)}" y="135" text-anchor="middle" font-size="10">${String(D.years[j]).slice(2)}</text>`).join(\'\')}</svg><p>2009: <b>${fmt(p.mean[0])}%</b> → 2024: <b>${fmt(p.mean[5])}%</b><br>Cambio: <b>${p.delta>0?\'+\':\'\'}${fmt(p.delta)} pp</b> · mínimo: ${p.low_year}<br>Silueta: ${fmt(m.silhouette_by_group[p.group])}<br>Jaccard mínimo / medio: <b>${fmt(p.jaccard_min)} / ${fmt(p.jaccard_mean)}</b></p><p class="small">${p.reference_match?`Coincidencia con K-means centrado G${p.reference_match.group+1}: Jaccard <b>${fmt(p.reference_match.jaccard)}</b><br>Jaccard mínimo al cambiar vecindad: <b>${fmt(p.neighbor_jaccard_min)}</b>`:\'\'}</p><div>${p.representatives.map(r=>`<button data-example="${r.key}" title="${esc(r.state)} · ${r.key} · distancia al centroide ${fmt(r.distance)}">${esc(r.name)} · ${esc(r.state)}</button>`).join(\'\')}</div><p class="muted">${$(\'metric\').value===\'centered\'?\'Curva: desviación de la media propia (pp).\':\'Curva: SV/LN (%), independientemente de otros indicadores.\'} ${p.jaccard_min==null?\'Jaccard por grupo no disponible en esta solución.\':\'Jaccard bajo indica que el grupo cambia al retirar una elección.\'}</p></article>`;}).join(\'\');\n $(\'profiles\').querySelectorAll(\'[data-example]\').forEach(b=>b.onclick=()=>{addPin(b.dataset.example);b.textContent=\'✓ \'+b.textContent.replace(/^✓ /,\'\');});\n if(!m.transition_matrix){$(\'transition\').innerHTML=\'\';return;}let mx=Math.max(...m.transition_matrix.flat());$(\'transition\').innerHTML=`<h3>${m.experiment===\'graph\'?\'¿Qué perfiles reaparecen con otro método?\':\'¿Cómo cambia la clasificación al centrar?\'}</h3><p class="small">ARI frente a ${m.experiment===\'graph\'?\'K-means centrado con el mismo k\':\'experimento 01 con el mismo método y k\'}: <b>${fmt(m.experiment===\'graph\'?m.centered_ari:m.level_ari)}</b>. Filas: grupos de referencia; columnas: grupos del modelo actual. Los números no implican correspondencia. Pasa el cursor para ver los cruces.</p><table><thead><tr><th>Referencia / actual</th>${m.sizes.map((_,i)=>\'<th>G\'+(i+1)+\'</th>\').join(\'\')}</tr></thead><tbody>${m.transition_matrix.map((row,i)=>\'<tr><th>G\'+(i+1)+\'</th>\'+row.map((n,j)=>`<td style="background:rgba(8,127,131,${n/mx*.65})" title="Referencia G${i+1} → actual G${j+1}: ${n} municipios">${n}</td>`).join(\'\')+\'</tr>\').join(\'\')}</tbody></table><p class="small muted">Cruces del modelo completo. Describen acuerdo de etiquetas, no migración ni cambios de voto.</p>`;\n}\n\n\nfunction minValid(xs){let vs=xs.filter(v=>v!=null);return vs.length?Math.min(...vs):null;}\nfunction renderGraph(m,rs){$(\'graphPanel\').hidden=m.experiment!==\'graph\';if(m.experiment!==\'graph\')return;let g=D.graphs[m.graph_index],idx=new Map(g.ids.map((id,i)=>[id,i]));$(\'graphFacts\').textContent=`${nf.format(g.n)} nodos · ${nf.format(g.edges)} enlaces · ${g.components} componente conexo · ${g.neighbors} vecinos. ${rs.length} municipios visibles con los filtros.`;\n let xy=g.xy,xs=xy.map(v=>v[0]),ys=xy.map(v=>v[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),x=v=>50+900*(v-xmin)/(xmax-xmin||1),y=v=>400-350*(v-ymin)/(ymax-ymin||1);\n $(\'graphPlot\').innerHTML=\'<rect x="50" y="50" width="900" height="350" fill="#f6f9f7"/>\'+rs.map((r,i)=>{let v=xy[idx.get(r.id)];return `<circle class="data-dot" data-i="${i}" cx="${x(v[0])}" cy="${y(v[1])}" r="4" opacity=".65" fill="${palette[r.clusterLabel]}"><title>${esc(r.name)} · ${esc(r.state)} · G${r.clusterLabel+1}</title></circle>`;}).join(\'\');\n $(\'graphPlot\').querySelectorAll(\'circle\').forEach(el=>{let r=rs[+el.dataset.i];el.onmousemove=e=>tooltip(e,r,5);el.onmouseleave=hideTip;el.onclick=()=>addPin(r.key);});\n $(\'graphRobustness\').innerHTML=`<p class="small">Acuerdo al cambiar la vecindad: ${(m.neighbor_ari||[]).map(o=>o.neighbors+\' vecinos: ARI <b>\'+fmt(o.ari)+\'</b>\').join(\' · \')}. Acuerdo con K-means centrado: <b>${fmt(m.centered_ari)}</b>. Una coincidencia baja indica que los métodos delimitan grupos distintos.</p>`;\n}\n\nfunction renderQuality(rows){let ys=D.years.map(y=>({year:y,files:D.audit.files.filter(f=>f.year===y)})),keys=Object.keys(D.audit.files[0]?.issues||{});$(\'auditSummary\').innerHTML=`<table><thead><tr><th>Año</th><th>Filas leídas</th>${keys.map(k=>`<th>${esc(k.replaceAll(\'_\',\' \'))}</th>`).join(\'\')}</tr></thead><tbody>${ys.map(o=>`<tr><td>${o.year}</td><td>${nf.format(o.files.reduce((a,f)=>a+f.rows,0))}</td>${keys.map(k=>`<td>${nf.format(o.files.reduce((a,f)=>a+f.issues[k],0))}</td>`).join(\'\')}</tr>`).join(\'\')}</tbody></table>`;\n let bad=rows.filter(r=>!r.eligible);$(\'exclusionTable\').innerHTML=`<p class="small">${nf.format(bad.length)} trayectorias fuera del modelo en esta selección. Se listan las primeras 200; el CSV descarga todas.</p><table><thead><tr><th>Municipio</th><th>Motivo</th></tr></thead><tbody>${bad.slice(0,200).map(r=>`<tr><td>${esc(r.name)} · ${r.key}</td><td>${r.geo!==\'verificado\'?\'Estado cartográfico: \'+esc(r.geo)+\'. \':\'\'}${r.reasons.map((v,j)=>v?D.years[j]+\': \'+esc(v):\'\').filter(Boolean).join(\'; \')}</td></tr>`).join(\'\')}</tbody></table>`;}\nfunction render(){let rs=selected();page=Math.min(page,Math.max(0,Math.ceil(rs.length/30)-1));$(\'nMunicipal\').textContent=nf.format(rs.length);$(\'nComplete\').textContent=nf.format(rs.filter(r=>r.complete).length);$(\'nGeo\').textContent=nf.format(rs.filter(r=>r.stable_sections).length);$(\'nMissing\').textContent=nf.format(rs.reduce((a,r)=>a+r.counts.filter(x=>!x).length,0));$(\'lineCaption\').textContent=`${rs.length>80?\'Primeros 80 municipios por nombre de \'+nf.format(rs.length):nf.format(rs.length)+\' municipios\'} · ${$(\'metric\').selectedOptions[0].text}. Filtra para reducir el número de líneas.`;lineChart(\'lines\',rs);scatter(rs);table(rs,\'municipalTable\');$(\'pageLabel\').textContent=`${rs.length?page+1:0} / ${Math.ceil(rs.length/30)}`;$(\'prev\').disabled=page===0;$(\'next\').disabled=(page+1)*30>=rs.length;renderCompare();renderModels();renderQuality(rs);}\nfunction downloadClusters(){let m=D.models[+$(\'model\').value];if(!m)return;let labels=new Map(m.ids.map((id,i)=>[id,m.labels[i]]));let rs=selected().filter(r=>labels.has(r.id)&&($(\'clusterGroup\').value===\'\'||labels.get(r.id)===+$(\'clusterGroup\').value));let rows=[[\'clave_INE\',\'municipio\',\'entidad\',\'cohorte_edad_2009\',\'sexo\',\'experimento\',\'modelo\',\'vecinos\',\'k\',\'grupo_provisional\',\'mismo_conjunto_secciones\',...D.years.map(y=>\'P_\'+y)]];rs.forEach(r=>rows.push([r.key,r.name,r.state,D.bands[r.cohort]+\'-\'+(D.bands[r.cohort]+2),r.sex,m.experiment,m.method,m.neighbors??\'\',m.k,labels.get(r.id)+1,r.stable_sections,...r.counts.map(x=>100*x[1]/x[0])]));let csv=\'\\ufeff\'+rows.map(row=>row.map(v=>{let t=String(v);if(typeof v===\'string\'&&/^[=+@-]/.test(t))t="\'"+t;return \'"\'+t.replaceAll(\'"\',\'""\')+\'"\';}).join(\',\')).join(\'\\r\\n\');let url=URL.createObjectURL(new Blob([csv],{type:\'text/csv;charset=utf-8\'})),a=document.createElement(\'a\');a.href=url;a.download=\'clasificacion_\'+m.experiment+\'_\'+m.method+(m.neighbors?\'_v\'+m.neighbors:\'\')+\'_k\'+m.k+\'.csv\';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}\nfunction download(){let rows=[[\'clave_INE\',\'municipio\',\'entidad\',\'cohorte_edad_2009\',\'sexo\',\'eleccion\',\'edad_min\',\'edad_max\',\'LN\',\'SV\',\'NV\',\'NS\',\'P\',\'P_especificada\',\'Q\',\'continuidad_territorial\',\'motivo_dato_ausente\']];selected().forEach(r=>D.years.forEach((yr,j)=>{let x=r.counts[j],age=D.bands[r.cohort]+yr-2009;rows.push([r.key,r.name,r.state,`${D.bands[r.cohort]}-${D.bands[r.cohort]+2}`,r.sex,yr,age,age+2,...(x||[\'\',\'\',\'\',\'\']),x?100*x[1]/x[0]:\'\',x&&x[1]+x[2]>0?100*x[1]/(x[1]+x[2]):\'\',x?100*x[3]/x[0]:\'\',r.geo,r.reasons[j]]);}));let csv=\'\\ufeff\'+rows.map(row=>row.map(v=>{let s=String(v);if(typeof v===\'string\'&&/^[=+@-]/.test(s))s="\'"+s;return \'"\'+s.replaceAll(\'"\',\'""\')+\'"\';}).join(\',\')).join(\'\\r\\n\');let a=document.createElement(\'a\'),url=URL.createObjectURL(new Blob([csv],{type:\'text/csv;charset=utf-8\'}));a.href=url;a.download=\'seleccion_generaciones.csv\';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}\nlet states=[...new Map(D.records.map(r=>[r.ed,r.state])).entries()].sort((a,b)=>a[0]-b[0]);$(\'state\').innerHTML=\'<option value="">Todas las entidades</option>\'+states.map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join(\'\');$(\'state\').value=\'\';\n$(\'status\').innerHTML=D.models.length?`<b>${D.models.length} soluciones exploratorias calculadas.</b> Se utilizan trayectorias completas. La cartografía pendiente no bloquea la segmentación; consulta la sensibilidad territorial en Agrupamientos.`:\'<b>Datos reales disponibles · agrupamiento pendiente de validación territorial.</b> Puedes explorar y comparar observaciones. Las líneas aún no acreditan continuidad de límites municipales; el código no ha asignado clústeres sin esa comprobación.\';\n[\'cohort\',\'sex\',\'state\',\'metric\'].forEach(id=>$(id).onchange=()=>{page=0;if(id===\'cohort\'||id===\'sex\')renderModels(true);render();});$(\'search\').oninput=()=>{page=0;render();};$(\'prev\').onclick=()=>{page--;render();};$(\'next\').onclick=()=>{page++;render();};$(\'clearPins\').onclick=()=>{pinned=[];renderCompare();};$(\'download\').onclick=download;$(\'downloadClusters\').onclick=downloadClusters;$(\'experiment\').onchange=()=>{renderModels(true);};$(\'model\').onchange=()=>renderModels();$(\'clusterGroup\').onchange=()=>renderModels();document.querySelectorAll(\'nav button\').forEach(b=>b.onclick=()=>{document.querySelectorAll(\'nav button\').forEach(x=>x.classList.toggle(\'active\',x===b));document.querySelectorAll(\'main>section\').forEach(s=>s.hidden=s.id!==b.dataset.tab);hideTip();});\n$(\'sourceTable\').innerHTML=`<table><thead><tr><th>Año</th><th>Archivo</th><th>SHA-256</th></tr></thead><tbody>${Object.entries(D.manifest.sources).map(([y,s])=>`<tr><td>${y}</td><td>${esc(s.filename)}</td><td class="filehash">${s.sha256}</td></tr>`).join(\'\')}</tbody></table>`;$(\'runtime\').textContent=JSON.stringify(D.manifest.runtime,null,2);$(\'build\').textContent=\'Versión \'+D.version+\' · generado \'+D.created_utc.slice(0,10);render();if(D.models.length)document.querySelector(\'[data-tab="clusters"]\').click();\n</script></body></html>\n'

def write_json(path,obj):
    Path(path).write_text(json.dumps(obj,ensure_ascii=False,allow_nan=False,separators=(',',':')),encoding='utf-8')
def rates(r,specified=False):
    return np.array([100*x[1]/(x[1]+x[2] if specified else x[0]) if (x[1]+x[2] if specified else x[0])>0 else np.nan for x in r['counts']])
def center(X):return X-X.mean(axis=1,keepdims=True)
def graph_embedding(X,q,maxk=8):
    n=len(X)
    if n<=max(q,maxk+1):return {'reason':'Muestra insuficiente','n':n},None,None
    dist,indices=NearestNeighbors(n_neighbors=q+1,metric='euclidean').fit(X).kneighbors(X)
    pairs=[[(int(j),float(d)) for j,d in zip(indices[i],dist[i]) if j!=i][:q] for i in range(n)]
    js=np.array([[j for j,d in p] for p in pairs]);ds=np.array([[d for j,d in p] for p in pairs])
    sigma=np.maximum(ds[:,6],1e-10)
    weights=np.exp(-np.minimum(ds**2/(sigma[:,None]*sigma[js]),700))
    W=csr_matrix((weights.ravel(),(np.repeat(np.arange(n),q),js.ravel())),shape=(n,n));W=W.maximum(W.T);W.setdiag(0);W.eliminate_zeros()
    nc,comp=connected_components(W,directed=False)
    info={'neighbors':q,'components':int(nc),'component_sizes':np.bincount(comp).tolist(),'edges':int(W.nnz//2),'n':n,'local_scale_neighbor':7}
    if nc!=1:info['reason']='Grafo desconectado: no se añaden enlaces artificiales';return info,None,W
    L=laplacian(W,normed=True)
    vals,U=eigsh(L,k=maxk+1,which='SM',tol=1e-8,maxiter=20000,v0=np.random.default_rng(0).normal(size=n))
    order=np.argsort(vals);vals=vals[order];U=U[:,order]
    info['eigenvalues']=vals.tolist()
    info['eigen_residual_max']=float(np.linalg.norm(L@U-U*vals,axis=0).max())
    for j in range(U.shape[1]):
        if U[np.argmax(np.abs(U[:,j])),j]<0:U[:,j]*=-1
    return info,U,W

def fit_embedding(U,k,seed=0):
    V=U[:,:k];V=V/np.maximum(np.linalg.norm(V,axis=1,keepdims=True),1e-15)
    return KMeans(n_clusters=k,n_init=30,max_iter=500,tol=1e-4,random_state=seed,algorithm='lloyd').fit_predict(V)
def ari(a,b):return float(adjusted_rand_score(a,b))
def jaccards(a,b,k):
    if b is None:return [None]*k
    return [max(float(np.sum((a==g)&(b==h))/np.sum((a==g)|(b==h))) for h in np.unique(b)) for g in range(k)]
def profile_summary(rs,X,labels,k,jacks):
    ps=[]
    for g in range(k):
        ix=np.flatnonzero(labels==g);raw=X[ix];mean=raw.mean(axis=0);delta=float(mean[-1]-mean[0]);V=center(raw)
        distances=np.linalg.norm(V-V.mean(axis=0),axis=1);seen=set();examples=[]
        for pos in np.argsort(distances,kind='stable'):
            r=rs[ix[pos]]
            if r['ed'] in seen:continue
            seen.add(r['ed']);examples.append({key:r[key] for key in ['id','key','name','state']});examples[-1]['distance']=float(distances[pos])
            if len(examples)==3:break
        js=[x[g] for x in jacks if x[g] is not None]
        ps.append({'group':g,'name':f"{'Ascenso' if delta>=0 else 'Descenso'} neto {delta:+.1f} pp · máximo en {YEARS[int(mean.argmax())]}",
            'n':len(ix),'mean':mean.tolist(),'centered_mean':V.mean(axis=0).tolist(),'delta':delta,'mean_level':float(mean.mean()),'peak_year':YEARS[int(mean.argmax())],
            'low_year':YEARS[int(mean.argmin())],'q_mean':np.array([[100*x[3]/x[0] for x in rs[i]['counts']] for i in ix]).mean(axis=0).tolist(),
            'jaccard_min':min(js) if js else None,'jaccard_mean':float(np.mean(js)) if js else None,'jaccard_n':len(js),'representatives':examples})
    return ps


def annotate_reference(models,baselines):
    for m in models:
        b=baselines[(m['cohort'],m['sex'],m['k'])]
        a=np.array(m['labels']);ref=np.array(b['labels'])
        for p in m['profiles']:
            A=a==p['group'];scores=[float(np.sum(A&(ref==h))/np.sum(A|(ref==h))) for h in range(m['k'])]
            h=int(np.argmax(scores));p['reference_match']={'group':h,'jaccard':scores[h],'intersection':int(np.sum(A&(ref==h))),'reference_n':int(np.sum(ref==h))}
    return models

def run(data,out):
    baselines={(m['cohort'],m['sex'],m['k']):m for m in data['models'] if m.get('experiment')=='centered' and m['method']=='kmeans'}
    models=[];graphs=[]
    for c,s in itertools.product(range(4),range(2)):
        rs=[r for r in data['records'] if r['cohort']==c and r['sex']==s and r['eligible']]
        raw=np.vstack([rates(r) for r in rs]);X=center(raw);Xs=center(np.vstack([rates(r,True) for r in rs]));valid=np.isfinite(Xs).all(axis=1)
        stable=np.array([r.get('stable_sections',False) for r in rs]);ids=[r['id'] for r in rs]
        with threadpool_limits(limits=1):
            for q in NEIGHBORS:
                print(f'Grafo cohorte={c} sexo={s} vecinos={q}: espectro y sensibilidades',flush=True)
                info,U,W=graph_embedding(X,q);info.update(cohort=c,sex=s,ids=ids);graphs.append(info)
                if U is None:continue
                info['xy']=U[:,1:3].tolist()
                jack=[graph_embedding(center(np.delete(raw,j,axis=1)),q) for j in range(6)]
                spec=graph_embedding(Xs[valid],q);terr=graph_embedding(X[stable],q)
                for k in range(2,9):
                    labels=fit_embedding(U,k);seeds=[fit_embedding(U,k,seed) for seed in range(10)]
                    seed_aris=[ari(a,b) for a,b in itertools.combinations(seeds,2)]
                    jl=[fit_embedding(v,k) if v is not None else None for _,v,_ in jack];jari=[ari(labels,a) if a is not None else None for a in jl];jg=[jaccards(labels,a,k) for a in jl]
                    b=baselines[(c,s,k)];assert b['ids']==ids
                    matrix=np.zeros((k,k),dtype=int)
                    for a,z in zip(b['labels'],labels):matrix[a,z]+=1
                    sil=silhouette_samples(X,labels)
                    m={'experiment':'graph','method':'spectral','neighbors':q,'cohort':c,'sex':s,'k':k,'ids':ids,'labels':labels.tolist(),'sizes':np.bincount(labels,minlength=k).tolist(),
                       'silhouette':float(sil.mean()),'silhouette_by_group':[float(sil[labels==g].mean()) for g in range(k)],'seed_ari_median':float(np.median(seed_aris)),'seed_ari_min':min(seed_aris),
                       'jackknife_ari':jari,'group_jaccard':np.array(jg,dtype=object).T.tolist(),'specified_n':int(valid.sum()),'specified_ari':ari(labels[valid],fit_embedding(spec[1],k)) if spec[1] is not None else None,
                       'territorial_n':int(stable.sum()),'territorial_ari':ari(labels[stable],fit_embedding(terr[1],k)) if terr[1] is not None else None,
                       'centered_ari':ari(b['labels'],labels),'transition_matrix':matrix.tolist(),'graph_index':len(graphs)-1,
                       'sensitivity_diagnostics':{'jackknife':[a for a,_,_ in jack],'specified':spec[0],'territorial':terr[0]},
                       'profiles':profile_summary(rs,raw,labels,k,jg)}
                    models.append(m)
                write_json(out/'grafos_checkpoint.json',{'models':models,'graphs':graphs})
                print(f'  {len(models)} soluciones terminadas',flush=True)
    for m in models:
        peers=[o for o in models if o['cohort']==m['cohort'] and o['sex']==m['sex'] and o['k']==m['k'] and o['neighbors']!=m['neighbors']]
        m['neighbor_ari']=[{'neighbors':o['neighbors'],'ari':ari(m['labels'],o['labels'])} for o in peers]
        for p in m['profiles']:
            js=[jaccards(np.array(m['labels']),np.array(o['labels']),m['k'])[p['group']] for o in peers]
            p['neighbor_jaccard_min']=min(js) if js else None
    annotate_reference(models,baselines)
    return models,graphs

def main():
    ap=argparse.ArgumentParser(description=__doc__,formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--base-html',type=Path,required=True);ap.add_argument('--output-dir',type=Path,default=Path('resultados_grafos'));args=ap.parse_args()
    src=args.base_html.resolve();out=args.output_dir.resolve();out.mkdir(parents=True,exist_ok=True)
    if out/'explorador_generaciones.html'==src:raise ValueError('Elige otra carpeta de salida para preservar el HTML de entrada')
    original=src.read_bytes();html=original.decode('utf-8');match=re.search(r'<script id="dataset" type="application/json">(.*?)</script>',html,re.S)
    if not match:raise ValueError('No es un explorador compatible')
    data=json.loads(match[1]);models,graphs=run(data,out)
    data['models']=[m for m in data['models'] if m.get('experiment')!='graph']+models;data['graphs']=graphs;data['version']='3.0'
    data['graph_manifest']={'base_sha256':hashlib.sha256(original).hexdigest(),'python':platform.python_version(),'numpy':np.__version__,'scipy':scipy.__version__,'sklearn':sklearn.__version__}
    from datetime import datetime,timezone
    data['created_utc']=datetime.now(timezone.utc).isoformat()
    write_json(out/'modelos_grafos.json',{'models':models,'graphs':graphs,'manifest':data['graph_manifest']})
    template=TEMPLATE if TEMPLATE is not None else html[:match.start(1)]+'__DATA__'+html[match.end(1):]
    (out/'explorador_generaciones.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False,allow_nan=False,separators=(',',':')).replace('<','\\u003c')),encoding='utf-8')
    assert hashlib.sha256(src.read_bytes()).hexdigest()==data['graph_manifest']['base_sha256']
    print(f'Finalizado: {len(models)} soluciones nuevas. {out / "explorador_generaciones.html"}',flush=True)
if __name__=='__main__':main()
